package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;import com.ruoyi.medical.contracts.*;import com.ruoyi.medical.identity.ApplicationSessionIdentity;import com.ruoyi.medical.persistence.mapper.*;import java.util.*;import java.time.LocalDateTime;import org.springframework.util.function.ThrowingSupplier;
/** Actual human decision producer, with distinct rejected evidence and full private-proof acceptance. */
public final class FormalAgentAcceptanceService {
 private final EnterpriseAccess access;private final FormalAgentPublicationSchema schema;private final PermissionSchema json;private final FormalAgentAcceptanceEvidence evidence;private final FormalAgentCandidateStore candidates;private final FormalAgentAcceptanceStore store;private final AgentPublicationJournal journal;private final AgentPublicationMapper versions;private final FormalAgentAcceptanceMapper mapper;private final ResourceReadAuthority resources;private final EvaluationService evaluations;
 public FormalAgentAcceptanceService(EnterpriseAccess access,FormalAgentPublicationSchema schema,PermissionSchema json,FormalAgentAcceptanceEvidence evidence,FormalAgentCandidateStore candidates,FormalAgentAcceptanceStore store,AgentPublicationJournal journal,AgentPublicationMapper versions,FormalAgentAcceptanceMapper mapper,ResourceReadAuthority resources,EvaluationService evaluations){this.access=access;this.schema=schema;this.json=json;this.evidence=evidence;this.candidates=candidates;this.store=store;this.journal=journal;this.versions=versions;this.mapper=mapper;this.resources=resources;this.evaluations=evaluations;}
 public JsonNode decide(ApplicationSessionIdentity.Verified subject,String context,String key,byte[] bytes)throws Exception{
  var request=schema.request("Accept",bytes).deepCopy();SimulationInputArtifactSchema.key(key);
  var replay=access.execute(subject,a->checked(()->{current(a,context);var prior=journal.prior(a,"ACCEPTANCE",key,request);if(prior==null){initial(a,request);return null;}read(a,prior.recordId());return schema.read(prior.receiptJson());}));if(replay!=null)return replay;
  var prepared="ACCEPT".equals(request.path("decision").asText())?evidence.prepare(subject,context,request,false):null;
  return access.execute(subject,a->checked(()->{
   current(a,context);var prior=journal.prior(a,"ACCEPTANCE",key,request);if(prior!=null){read(a,prior.recordId());return schema.read(prior.receiptJson());}
   var candidate=initial(a,request);var grant=resources.require(a,FormalAgentCandidateService.governance(a,candidate.binding().projectId()),"agent.publish","AGENT_PUBLICATION");var evaluationRef=FormalAgentCandidateDependencies.basis(request.required("evaluation"));var snapshot=evaluations.requireFormalDefinitionMetadata(a,evaluationRef.version_id());if(!snapshot.row().contentHash().equals(evaluationRef.content_sha256())||!Objects.equals(snapshot.row().projectId(),candidate.binding().projectId())||snapshot.definition().request().candidates().stream().noneMatch(c->c.version_id().equals(candidate.binding().versionId())&&c.content_sha256().equals(candidate.binding().contentSha256())))bad();
   FormalAgentAcceptanceEvidence.Verified proof=prepared==null?null:evidence.require(a,request,prepared);String classification=proof==null?FormalAgentAcceptanceEvidence.maxClassification(candidate.binding().classification(),snapshot.row().classification()):proof.classification();String decision=request.required("decision").asText(),id=UUID.randomUUID().toString();var values=journal.values(a);var now=(LocalDateTime)values.get("now");var content=json.object().put("schema_version","1.0.0").put("acceptance_id",id).put("tenant_id",a.context().tenant_id()).put("project_id",candidate.binding().projectId()).put("decision",decision).put("accepted_by",a.actorId()).put("accepted_at",now.toInstant(java.time.ZoneOffset.UTC).toString()).put("classification",classification);
   for(String field:List.of("candidate","evaluation","statistics_policy"))content.set(field,request.required(field).deepCopy());content.set("execution_policy",json.tree(new PermissionProtocol.Basis(candidate.binding().policyVersionId(),candidate.binding().policySha256())));
   var auth=json.object();auth.put("identity_mode",a.bindingView().mode());auth.set("governance",AgentPublicationWitness.tree(grant));String release=null;
   if(proof!=null){proof.requireConsumer(a);release=UUID.randomUUID().toString();var manifest=(com.fasterxml.jackson.databind.node.ObjectNode)candidate.fixed().required("manifest").deepCopy();manifest.put("tenant_id",a.context().tenant_id()).put("agent_version_id",candidate.binding().versionId()).put("agent_version_sha256",candidate.binding().contentSha256()).put("release_id",release).put("evaluation_id",snapshot.row().evaluationId()).put("evaluation_sha256",snapshot.row().contentHash());
    byte[] definition;try(var in=Objects.requireNonNull(getClass().getResourceAsStream("/agent-release.schema.json"))){definition=in.readAllBytes();}var validated=new AgentReleaseManifestSchema(definition,SchemaCatalogue.fromClasspath()).bind(schema.canonical(manifest).getBytes(java.nio.charset.StandardCharsets.UTF_8));
    content.set("manifest",manifest);content.put("manifest_sha256",validated.sha256()).put("result_sha256",proof.resultHash()).put("score_history_sha256",proof.scoreHistoryHash()).put("statistics_sha256",proof.statisticsHash()).put("execution_evidence_sha256",proof.executionHash());content.set("qualified_scores",proof.qualifiedScores());auth.set("professional_evidence",proof.authorizations());schema.validate("Accepted",content);
   }else schema.validate("Rejected",content);
   snapshot.requireUnchanged();String hash=schema.hash(content);values.put("projectId",candidate.binding().projectId());values.put("versionId",id);values.put("entityKind","AGENT_PUBLICATION_RECORD");values.put("contentHash",hash);one(versions.insertVersion(values));var saved=journal.save(a,candidate.binding().projectId(),id,"ACCEPTANCE",candidate.binding().versionId(),key,request,content,auth,classification,now);
   values.put("candidateVersionId",candidate.binding().versionId());values.put("candidateSha256",candidate.binding().contentSha256());values.put("evaluationId",snapshot.row().evaluationId());values.put("evaluationSha256",snapshot.row().contentHash());values.put("expectedRevision",request.path("expected_revision").asText());values.put("status",proof==null?"DRAFT":"REVIEW_PENDING");one(mapper.decideCandidate(values));
   if(proof!=null){values.put("acceptanceId",id);values.put("releaseId",release);values.put("manifestSha256",content.required("manifest_sha256").asText());values.put("contentSha256",hash);values.put("decision",decision);values.put("manifest",schema.manifest());values.put("classification",classification);one(mapper.insertAcceptance(values));var checked=store.metadata(a,new PermissionProtocol.Basis(id,hash),"AGENT_PUBLICATION");if(!schema.canonical(content).equals(schema.canonical(checked.content())))bad();}
   read(a,id);return schema.read(saved.receiptJson());
  }));
 }
 private FormalAgentCandidateStore.Loaded initial(EnterpriseAccess.Admission a,JsonNode request)throws Exception{var loaded=candidates.read(a,FormalAgentCandidateDependencies.basis(request.required("candidate")),"AGENT_PUBLICATION");if(loaded.binding().createdBy().equals(a.actorId()))deny();resources.require(a,FormalAgentCandidateService.governance(a,loaded.binding().projectId()),"agent.publish","AGENT_PUBLICATION");if(!request.path("expected_revision").asText().equals(loaded.agent().revision().toString()))throw new TenantAccessException(ErrorCode.REVISION_CONFLICT);if(!Set.of("DRAFT","VALIDATING","EVALUATING","REVIEW_PENDING").contains(loaded.agent().status()))throw new TenantAccessException(ErrorCode.ACTION_STALE);return loaded;}
 JsonNode read(EnterpriseAccess.Admission a,String recordId)throws Exception{var original=journal.read(a,recordId);if(!"ACCEPTANCE".equals(original.kind()))bad();var content=schema.read(original.contentJson());var request=schema.validate("Accept",schema.read(original.requestJson()));var candidate=candidates.read(a,FormalAgentCandidateDependencies.basis(request.required("candidate")),"AGENT_PUBLICATION");resources.require(a,FormalAgentCandidateService.governance(a,candidate.binding().projectId()),"configuration.read","AGENT_PUBLICATION");AgentPublicationWitness.requireGovernance(original,schema.read(original.authorizationsJson()),"agent.publish","AGENT_PUBLICATION",json);if(candidate.binding().createdBy().equals(original.createdBy())||!original.resourceId().equals(candidate.binding().versionId())||!original.recordId().equals(content.path("acceptance_id").asText())||!original.createdBy().equals(content.path("accepted_by").asText())||!original.createdAt().toInstant(java.time.ZoneOffset.UTC).toString().equals(content.path("accepted_at").asText())||!Objects.equals(original.projectId(),candidate.binding().projectId())||!original.tenantId().equals(content.path("tenant_id").asText()))bad();for(String field:List.of("candidate","evaluation","statistics_policy","decision"))if(!request.required(field).equals(content.required(field)))bad();schema.validate("ACCEPT".equals(request.path("decision").asText())?"Accepted":"Rejected",content);return content;}
 public JsonNode read(ApplicationSessionIdentity.Verified subject,String context,String id){return access.execute(subject,a->checked(()->{current(a,context);return read(a,id);}));}
 public JsonNode receipt(ApplicationSessionIdentity.Verified subject,String context,String id,String operation){return access.execute(subject,a->checked(()->{current(a,context);var original=journal.read(a,id);if(!original.createdBy().equals(a.actorId())||!original.operationId().equals(operation))deny();read(a,id);return schema.read(original.receiptJson());}));}
 private static void current(EnterpriseAccess.Admission a,String context){if(!a.context().context_revision().equals(context))throw new TenantAccessException(ErrorCode.CONTEXT_CHANGED);}private static <T>T checked(ThrowingSupplier<T> fn){return fn.get();}private static void one(int n){if(n!=1)bad();}private static void bad(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}private static void deny(){throw new TenantAccessException(ErrorCode.ACCESS_DENIED);}
}
